    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def validSubstringCount(self, word1: str, word2: str) -> int:\n        diff = [0] * 26\n        for c in word2:\n            diff[ord(c) - ord('a')] -= 1\n\n        res = 0\n        cnt = sum(1 for c in diff if c < 0)\n\n        def update(c: int, add: int):\n            nonlocal cnt\n            diff[c] += add\n            if add == 1 and diff[c] == 0:\n                # \u8868\u660e diff[c] \u7531 -1 \u53d8\u4e3a 0\n                cnt -= 1\n            elif add == -1 and diff[c] == -1:\n                # \u8868\u660e diff[c] \u7531 0 \u53d8\u4e3a -1\n                cnt += 1\n\n        l, r = 0, 0\n        while l < len(word1):\n            while r < len(word1) and cnt > 0:\n                update(ord(word1[r]) - ord('a'), 1)\n                r += 1\n            if cnt == 0:\n                res += len(word1) - r + 1\n            update(ord(word1[l]) - ord('a'), -1)\n            l += 1\n\n        return res\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.validSubstringCount(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
