    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def smallestRange(self, nums: List[List[int]]) -> List[int]:\n        rangeLeft, rangeRight = -10**9, 10**9\n        maxValue = max(vec[0] for vec in nums)\n        priorityQueue = [(vec[0], i, 0) for i, vec in enumerate(nums)]\n        heapq.heapify(priorityQueue)\n\n        while True:\n            minValue, row, idx = heapq.heappop(priorityQueue)\n            if maxValue - minValue < rangeRight - rangeLeft:\n                rangeLeft, rangeRight = minValue, maxValue\n            if idx == len(nums[row]) - 1:\n                break\n            maxValue = max(maxValue, nums[row][idx + 1])\n            heapq.heappush(priorityQueue, (nums[row][idx + 1], row, idx + 1))\n        \n        return [rangeLeft, rangeRight]\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.smallestRange(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
