    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\nclass MedianFinder:\n\n    def __init__(self):\n        self.queMin = list()\n        self.queMax = list()\n\n    def addNum(self, num: int) -> None:\n        queMin_ = self.queMin\n        queMax_ = self.queMax\n\n        if not queMin_ or num <= -queMin_[0]:\n            heapq.heappush(queMin_, -num)\n            if len(queMax_) + 1 < len(queMin_):\n                heapq.heappush(queMax_, -heapq.heappop(queMin_))\n        else:\n            heapq.heappush(queMax_, num)\n            if len(queMax_) > len(queMin_):\n                heapq.heappush(queMin_, -heapq.heappop(queMax_))\n        \n    def findMedian(self) -> float:\n        queMin_ = self.queMin\n        queMax_ = self.queMax\n\n        if len(queMin_) > len(queMax_):\n            return -queMin_[0]\n        return (-queMin_[0] + queMax_[0]) / 2\n\ndef main():\n    _lines = [x for x in sys.stdin.read().split('\\n') if x.strip() != '']\n    _ops = json.loads(_lines[0])\n    _args = json.loads(_lines[1]) if len(_lines) > 1 else []\n    _obj = None\n    _out = []\n    for _i, _op in enumerate(_ops):\n        _a = _args[_i] if _i < len(_args) else []\n        if _i == 0:\n            _obj = MedianFinder(*_a)\n            _out.append(None)\n        else:\n            _out.append(getattr(_obj, _op)(*_a))\n    print(json.dumps(_out, separators=(',', ':')))\n\nmain()\n",
