    "LeetCode 1703",
    "hard",
    "\u53cc\u6307\u9488/\u6ed1\u52a8\u7a97\u53e3",
    "\u7ed9\u4f60\u4e00\u4e2a\u6574\u6570\u6570\u7ec4\u00a0nums\u00a0\u548c\u4e00\u4e2a\u6574\u6570\u00a0k\u00a0\u3002\u00a0nums \u4ec5\u5305\u542b\u00a00\u00a0\u548c\u00a01\u00a0\u3002\u6bcf\u4e00\u6b21\u79fb\u52a8\uff0c\u4f60\u53ef\u4ee5\u9009\u62e9 \u76f8\u90bb\u00a0\u4e24\u4e2a\u6570\u5b57\u5e76\u5c06\u5b83\u4eec\u4ea4\u6362\u3002\n\n\u8bf7\u4f60\u8fd4\u56de\u4f7f\u00a0nums\u00a0\u4e2d\u5305\u542b\u00a0k\u00a0\u4e2a \u8fde\u7eed\u00a01\u00a0\u7684 \u6700\u5c11\u00a0\u4ea4\u6362\u6b21\u6570\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1anums = [1,0,0,1,0,1], k = 2\n\u8f93\u51fa\uff1a1\n\u89e3\u91ca\uff1a\u5728\u7b2c\u4e00\u6b21\u64cd\u4f5c\u65f6\uff0cnums \u53ef\u4ee5\u53d8\u6210 [1,0,0,0,1,1] \u5f97\u5230\u8fde\u7eed\u4e24\u4e2a 1 \u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1anums = [1,0,0,0,0,0,1,1], k = 3\n\u8f93\u51fa\uff1a5\n\u89e3\u91ca\uff1a\u901a\u8fc7 5 \u6b21\u64cd\u4f5c\uff0c\u6700\u5de6\u8fb9\u7684 1 \u53ef\u4ee5\u79fb\u5230\u53f3\u8fb9\u76f4\u5230 nums \u53d8\u4e3a [0,0,0,0,0,1,1,1] \u3002\n```\n\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165\uff1anums = [1,1,0,1], k = 2\n\u8f93\u51fa\uff1a0\n\u89e3\u91ca\uff1anums \u5df2\u7ecf\u6709\u8fde\u7eed 2 \u4e2a 1 \u4e86\u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= nums.length <= 105\n\n\tnums[i] \u8981\u4e48\u662f\u00a00\u00a0\uff0c\u8981\u4e48\u662f\u00a01\u00a0\u3002\n\n\t1 <= k <= sum(nums)",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1anums\u3001k\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def minMoves(self, nums: List[int], k: int) -> int:\n        g, preSum = [], [0]\n        for i, num in enumerate(nums):\n            if num == 1:\n                g.append(i - len(g))\n                preSum.append(preSum[-1] + g[-1])\n        m, res = len(g), inf\n        for i in range(m - k + 1):\n            mid = i + k // 2\n            r = g[mid]\n            res = min(res, (1 - k % 2) * r + (preSum[i + k] - preSum[mid + 1]) - (preSum[mid] - preSum[i]))\n        return res\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.minMoves(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
