    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def maxDifference(self, s: str, k: int) -> int:\n        def getStatus(cnt_a: int, cnt_b: int) -> int:\n            return ((cnt_a & 1) << 1) | (cnt_b & 1)\n        \n        n = len(s)\n        ans = float(\"-inf\")\n        for a in [\"0\", \"1\", \"2\", \"3\", \"4\"]:\n            for b in [\"0\", \"1\", \"2\", \"3\", \"4\"]:\n                if a == b:\n                    continue\n                \n                best = [float(\"inf\")] * 4\n                cnt_a = cnt_b = 0\n                prev_a = prev_b = 0\n                left = -1\n                for right in range(n):\n                    cnt_a += (s[right] == a)\n                    cnt_b += (s[right] == b)\n                    while right - left >= k and cnt_b - prev_b >= 2:\n                        left_status = getStatus(prev_a, prev_b)\n                        best[left_status] = min(best[left_status], prev_a - prev_b)\n                        left += 1\n                        prev_a += (s[left] == a)\n                        prev_b += (s[left] == b)\n                    \n                    right_status = getStatus(cnt_a, cnt_b)\n                    if best[right_status ^ 0b10] != float(\"inf\"):\n                        ans = max(ans, cnt_a - cnt_b - best[right_status ^ 0b10])\n\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.maxDifference(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
    "int",
