    "\u8f93\u51fa double[] \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass DualHeap:\n    def __init__(self, k: int):\n        # \u5927\u6839\u5806\uff0c\u7ef4\u62a4\u8f83\u5c0f\u7684\u4e00\u534a\u5143\u7d20\uff0c\u6ce8\u610f python \u6ca1\u6709\u5927\u6839\u5806\uff0c\u9700\u8981\u5c06\u6240\u6709\u5143\u7d20\u53d6\u76f8\u53cd\u6570\u5e76\u4f7f\u7528\u5c0f\u6839\u5806\n        self.small = list()\n        # \u5c0f\u6839\u5806\uff0c\u7ef4\u62a4\u8f83\u5927\u7684\u4e00\u534a\u5143\u7d20\n        self.large = list()\n        # \u54c8\u5e0c\u8868\uff0c\u8bb0\u5f55\u300c\u5ef6\u8fdf\u5220\u9664\u300d\u7684\u5143\u7d20\uff0ckey \u4e3a\u5143\u7d20\uff0cvalue \u4e3a\u9700\u8981\u5220\u9664\u7684\u6b21\u6570\n        self.delayed = collections.Counter()\n\n        self.k = k\n        # small \u548c large \u5f53\u524d\u5305\u542b\u7684\u5143\u7d20\u4e2a\u6570\uff0c\u9700\u8981\u6263\u9664\u88ab\u300c\u5ef6\u8fdf\u5220\u9664\u300d\u7684\u5143\u7d20\n        self.smallSize = 0\n        self.largeSize = 0\n\n\n    # \u4e0d\u65ad\u5730\u5f39\u51fa heap \u7684\u5806\u9876\u5143\u7d20\uff0c\u5e76\u4e14\b\u66f4\u65b0\u54c8\u5e0c\u8868\n    def prune(self, heap: List[int]):\n        while heap:\n            num = heap[0]\n            if heap is self.small:\n                num = -num\n            if num in self.delayed:\n                self.delayed[num] -= 1\n                if self.delayed[num] == 0:\n                    self.delayed.pop(num)\n                heapq.heappop(heap)\n            else:\n                break\n    \n    # \u8c03\u6574 small \u548c large \u4e2d\u7684\u5143\u7d20\u4e2a\u6570\uff0c\u4f7f\u5f97\u4e8c\u8005\u7684\u5143\u7d20\u4e2a\u6570\u6ee1\u8db3\u8981\u6c42\n    def makeBalance(self):\n        if self.smallSize > self.largeSize + 1:\n            # small \u6bd4 large \u5143\u7d20\u591a 2 \u4e2a\n            heapq.heappush(self.large, -self.small[0])\n            heapq.heappop(self.small)\n            self.smallSize -= 1\n            self.largeSize += 1\n            # small \u5806\u9876\u5143\u7d20\u88ab\u79fb\u9664\uff0c\u9700\u8981\u8fdb\u884c prune\n            self.prune(self.small)\n        elif self.smallSize < self.largeSize:\n            # large \u6bd4 small \u5143\u7d20\u591a 1 \u4e2a\n            heapq.heappush(self.small, -self.large[0])\n            heapq.heappop(self.large)\n            self.smallSize += 1\n            self.largeSize -= 1\n            # large \u5806\u9876\u5143\u7d20\u88ab\u79fb\u9664\uff0c\u9700\u8981\u8fdb\u884c prune\n            self.prune(self.large)\n\n    def insert(self, num: int):\n        if not self.small or num <= -self.small[0]:\n            heapq.heappush(self.small, -num)\n            self.smallSize += 1\n        else:\n            heapq.heappush(self.large, num)\n            self.largeSize += 1\n        self.makeBalance()\n\n    def erase(self, num: int):\n        self.delayed[num] += 1\n        if num <= -self.small[0]:\n            self.smallSize -= 1\n            if num == -self.small[0]:\n                self.prune(self.small)\n        else:\n            self.largeSize -= 1\n            if num == self.large[0]:\n                self.prune(self.large)\n        self.makeBalance()\n\n    def getMedian(self) -> float:\n        return float(-self.small[0]) if self.k % 2 == 1 else (-self.small[0] + self.large[0]) / 2\n\n\nclass Solution:\n    def medianSlidingWindow(self, nums: List[int], k: int) -> List[float]:\n        dh = DualHeap(k)\n        for num in nums[:k]:\n            dh.insert(num)\n        \n        ans = [dh.getMedian()]\n        for i in range(k, len(nums)):\n            dh.insert(nums[i])\n            dh.erase(nums[i - k])\n            ans.append(dh.getMedian())\n        \n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.medianSlidingWindow(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
