    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def findSubstring(self, s: str, words: List[str]) -> List[int]:\n        res = []\n        m, n, ls = len(words), len(words[0]), len(s)\n        for i in range(n):\n            if i + m * n > ls:\n                break\n            differ = Counter()\n            for j in range(m):\n                word = s[i + j * n: i + (j + 1) * n]\n                differ[word] += 1\n            for word in words:\n                differ[word] -= 1\n                if differ[word] == 0:\n                    del differ[word]\n            for start in range(i, ls - m * n + 1, n):\n                if start != i:\n                    word = s[start + (m - 1) * n: start + m * n]\n                    differ[word] += 1\n                    if differ[word] == 0:\n                        del differ[word]\n                    word = s[start - n: start]\n                    differ[word] -= 1\n                    if differ[word] == 0:\n                        del differ[word]\n                if len(differ) == 0:\n                    res.append(start)\n        return res\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.findSubstring(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
